not routed or rendered \u2014 consumers\n    // must skip any edge with `isLayoutOnly: true`.\n    const toLabelVirtual: Edge = {\n      id: `${edge.id}-to-label`,\n      start: edge.start,\n      end: labelNodeId,\n      type: 'normal',\n      isLayoutOnly: true,\n    } as unknown as Edge;\n    const fromLabelVirtual: Edge = {\n      id: `${edge.id}-from-label`,\n      start: labelNodeId,\n      end: edge.end,\n      type: 'normal',\n      isLayoutOnly: true,\n    } as unknown as Edge;\n\n    layoutOnlyEdges.push(toLabelVirtual, fromLabelVirtual);\n  }\n\n  const newNodes = [...data.nodes, ...nodesToAdd];\n  const newEdges = [...data.edges, ...layoutOnlyEdges];\n\n  return {\n    ...data,\n    nodes: newNodes,\n    edges: newEdges,\n  };\n}\n", "const EPS = 1e-3;\n\nexport interface Point {\n  x: number;\n  y: number;\n}\n\nexport type RectSide = 'top' | 'bottom' | 'left' | 'right';\n\nexport interface RectBounds {\n  left: number;\n  right: number;\n  top: number;\n  bottom: number;\n}\n\nexport interface RectEntry {\n  id: string;\n  rect: RectBounds;\n}\n\nexport interface NodeBoundsInfo extends RectEntry {\n  cx: number;\n  cy: number;\n}\n\nexport interface NodePairGeometry {\n  srcId: string;\n  dstId: string;\n  srcInfo: NodeBoundsInfo;\n  dstInfo: NodeBoundsInfo;\n  collinearX: boolean;\n  collinearY: boolean;\n}\n\nexport interface LayoutNodeRect extends RectBounds {\n  nodeId: string;\n}\n\nexport interface ThreeSegmentRoute {\n  kind: 'HVH' | 'VHV';\n  p0: Point;\n  p1: Point;\n  p2: Point;\n  p3: Point;\n}\n\nexport interface OrthogonalSegment {\n  index: number;\n  a: Point;\n  b: Point;\n  horizontal: boolean;\n  vertical: boolean;\n}\n\ninterface EdgeSegmentInput {\n  points?: Point[];\n  isLayoutOnly?: boolean;\n}\n\ninterface NodeBoundsInput {\n  id?: string;\n  x?: number;\n  y?: number;\n  width?: number;\n  height?: number;\n  isGroup?: boolean;\n  isEdgeLabel?: boolean;\n}\n\ninterface RectNodeInput {\n  x?: number;\n  y?: number;\n  width?: nu