minalLanes,\n  shiftLeftLaneTitleBandsLeftOfRails,\n  shortcutRedundantOrthogonalJogs,\n  swapDestinationTerminalTailsToReduceCrossings,\n} from './direction/materializedGeometry.js';\nimport { simplifyDetouredEdges } from './direction/detourSimplification.js';\nimport { anchorLabelsToPolyline } from './direction/labelAnchoring.js';\nimport { straightenCollinearSiblingDetours } from './direction/siblingSharedFaceRouting.js';\nimport { nudgeSharedInteriorSubpaths } from './direction/sharedTrackNudging.js';\nexport { validateSwimlanesLayout } from './direction/validation.js';\n\n/** Applies direction transforms and post-routing cleanup to a swimlane layout. */\nexport function postProcessSwimlaneLayout(layout: LayoutData, direction?: string): void {\n  const nodes = layout.nodes ?? [];\n  const edges = layout.edges ?? [];\n  const contentNodes = nodes.filter((n) => !n.isGroup);\n\n  // TB is the canonical orientation. LR/RL rotate rank progression onto X;\n  // BT mirrors the canonical Y progression. Cleanup passes below operate in\n  // whichever coordinate system this step leaves behind.\n  if (\n    (direction === 'LR' || direction === 'RL') &&\n    contentNodes.length > 0 &&\n    !applyLrDirectionTransform(layout, direction)\n  ) {\n    return;\n  }\n\n  if (direction === 'BT' && contentNodes.length > 0 && !applyBtDirectionTransform(layout)) {\n    return;\n  }\n\n  for (const edge of edges) {\n    if ((edge as { isLayoutOnly?: boolean }).isLayoutOnly) {\n      continue;\n    }\n    const pts = (edge as { points?: { x: number; y: number }[] }).points;\n    if (!pts || pts.length < 2) {\n      continue;\n    }\n    (edge as { points: { x: number; y: number }[] }).points = simplifyPolyline(\n      orthogonalizePolyline(pts)\n    );\n  }\n\n  simplifyDetouredEdges(edges as any[], nodes);\n\n  // Prefer shorter sibling routes when a local port shift keeps them clear.\n  straightenCollinearSiblingDetours(edges as any[], nodes);\n\n  // Swap a source port only when it produces a clear L-shape with fewer bends.\n  portSwapToLShape(edges as any[], nodes);\n\n  const nodeByIdMap = new Map<string, any>();\n  for (const n of nodes) {\n    nodeByIdMap.set(String(n.id), n);\n  }\n  // Initial label anchoring against the routed polylines. The cleanup passes\n  // below (nudging, terminal-lane splits, crossing resolution) can still reshape\n  // these polylines, so labels are re-anchored once more at the end.\n  anchorLabelsToPolyline(edges, nodeByIdMap);\n\n  clipEdgeEndpointsToNodeBoundaries(edges, nodeByIdMap);\n\n  // Retarget short terminal stubs that are hidden by endpoint clipping.\n  collapseShortTerminalStub(edges, nodeByIdMap);\n\n  // Wybrow-style shared-track nudge. The router may legitimately bundle\n  // connectors onto the same rail, but before rendering those coincident\n  // middle rails must be separated into nearby parallel tracks. This pass\n  // keeps endpoint stubs pinned and only offsets interior H/V segments whose\n  // same-axis span overlaps another edge.\n  nudgeSharedInteriorSubpaths(edges, nodeByIdMap);\n\n  // Materialized-render terminal lane split. The raw layout can still look\n  // valid while the renderer's endpoint clipping creates coincident first/last\n  // stubs on a shared node face. Split those visible terminal rails before the\n  // endpoint-duplication handoff pins them.\n  separateSharedRenderedTerminalLanes(edges, nodeByIdMap);\n\n  // Once terminal lanes have been separated, some earlier same-track detours\n  // become unnecessary. Remove only provably redundant rectangular doglegs;\n  // safety checks preserve obstacle clearance and the newly split lanes.\n  collapseRedundantRectangularDoglegs(edges, nodeByIdMap);\n\n  // Same-side rails can be routed just inside a taller intervening node's\n  // border. Lift those rails outside the blocker before crossing cleanup.\n  liftObstacleHuggingSameSideRails(edges, nodeByIdMap);\n\n  // Some shared-destination crossings only improve when two terminal ports\n  // exchange places together. Try that bounded transaction before falling back\n  // to whole-edge reroutes.\n  swapDestinationTerminalTailsToReduceCrossings(edges, nodeByIdMap);\n\n  const finalizeRenderedEdges = (): void => {\n    resolveRenderedOrthogonalCrossings(edges, nodeByIdMap);\n    reassignCrossingExternalRailChannels(edges, nodeByIdMap);\n    shortcutRedundantOrthogonalJogs(edges, nodeByIdMap);\n    anchorLabelsToPolyline(edges, nodeByIdMap);\n    prepareEdgeEndpointsForRenderer(edges, nodeByIdMap);\n    liftObstacleHuggingSameSideRails(edges, nodeByIdMap);\n    anchorLabelsToPolyline(edges, nodeByIdMap);\n    prepareEdgeEndpointsForRenderer(edges, nodeByIdMap);\n  };\n\n  // Wybrow-style crossing cleanup for the materialized render geometry. This\n  // pass only activates when strict H/V crossings remain after the lower-level\n  // nudging passes. It tries bounded port-pair and outer-channel candidates,\n  // preserving obstacle clearance and accepting only candidates that reduce the\n  // rendered crossing count or shorten an equally crossing route.\n  finalizeRenderedEdges();\n\n  // Renderer endpoint preparation materializes the visible endpoint geometry.\n  // Run the shared-track pass once more on that visible shape, then refresh\n  // labels and endpoint handoff. `prepareEdgeEndpointsForRenderer` is\n  // idempotent, so unchanged edges do not accumulate duplicate endpoints.\n  nudgeSharedInteriorSubpaths(edges, nodeByIdMap);\n\n  // Endpoint preparation materializes the renderer-facing terminal stubs. In\n  // long return-edge cases those stubs can reveal a crossing that was not\n  // present in the pre-materialized route, so run the bounded cleanup once\n  // more and then re-prepare the endpoints it reshaped.\n  finalizeRenderedEdges();\n\n  // Swimlane title bands are visual headers, not routing obstacles. After all\n  // edge geometry is final, move the aligned title bands out of any clear rail\n  // that still crosses the title section.\n  liftTopLaneTitleBandsAboveRails(edges, nodeByIdMap);\n  shiftLeftLaneTitleBandsLeftOfRails(edges, nodeByIdMap);\n  // Moving one aligned title band can expose a second title/rail interaction\n  // after the group bounds settle. The passes are idempotent, so one bounded\n  // repeat keeps headers out of late crossing-cleanup routes without rerouting\n  // the edges again.\n  liftTopLaneTitleBandsAboveRails(edges, nodeByIdMap);\n  shiftLeftLaneTitleBandsLeftOfRails(edges, nodeByIdMap);\n}\n", "import type { Graph, EdgeRef, NodeId } from './helpers.js';\n// cspell:ignore acyclicity topo indeg preds succs\n\n// Normalize/validate a Graph view; ensure nodeById exists and edges refer to known nodes\nexport function normalizeGraph(g: Graph): Graph {\n  const nodeById = new Map(g.nodeById);\n  // Filter edges with unknown endpoints and de-duplicate by id+endpoints\n  const seen = new Set<string>();\n  const edges: EdgeRef[] = [];\n  for (const e of g.edges) {\n    if (!nodeById.has(e.src) || !nodeById.has(e.dst)) {\n      continue;\n    }\n    const key = `${e.id}:${e.src}->${e.dst}`;\n    if (seen.has(key)) {\n      continue;\n    }\n    seen.add(key);\n    edges.push(e);\n  }\n  const nodes = [...nodeById.keys()];\n  return { nodes, edges, layout: g.layout, nodeById };\n}\n\n// Return incoming edges for v\nexport function incoming(g: Graph, v: NodeId): EdgeRef[] {\n  return g.edges.filter((e) => e.dst === v);\n}\n\n// Return outgoing edges for v\nexport function outgoing(g: Graph, v: NodeId): EdgeRef[] {\n  return g.edges.filter((e) => e.src === v);\n}\n\nexport function buildSuccessorMap(g: Graph): Map<NodeId, NodeId[]> {\n  const succs = new Map<NodeId, NodeId[]>();\n  for (const v of g.nodes) {\n    succs.set(v, []);\n  }\n  for (const e of g.edges) {\n    succs.get(e.src)!.push(e.dst);\n  }\n  return succs;\n}\n\nexport function buildSortedSuccessorMap(g: Graph): Map<NodeId, NodeId[]> {\n  const succs = buildSuccessorMap(g);\n  for (const successors of succs.values()) {\n    successors.sort((a, b) => a.localeCompare(b));\n  }\n  return succs;\n}\n\nexport function buildInDegreeMap(g: Graph): Map<NodeId, number> {\n  const indeg = new Map<NodeId, number>();\n  for (const v of g.nodes) {\n    indeg.set(v, 0);\n  }\n  for (const e of g.edges) {\n    indeg.set(e.dst, (indeg.get(e.dst) ?? 0) + 1);\n  }\n  return indeg;\n}\n\nexport function sortedZeroInDegreeNodes(indeg: Map<NodeId, number>): NodeId[] {\n  return [...indeg.entries()]\n    .filter(([, degree]) => degree === 0)\n    .map(([id]) => id)\n    .sort((a, b) => a.localeCompare(b));\n}\n\nexport function buildPredecessorSuccessorMaps(\n  g: Graph,\n  includeEdge: (edge: EdgeRef) => boolean = () => true\n): { preds: Map<NodeId, NodeId[]>; succs: Map<NodeId, NodeId[]> } {\n  const preds = new Map<NodeId, NodeId[]>();\n  const succs = new Map<NodeId, NodeId[]>();\n  for (const v of g.nodes) {\n    preds.set(v, []);\n    succs.set(v, []);\n  }\n  for (const e of g.edges) {\n    if (!includeEdge(e)) {\n      continue;\n    }\n    succs.get(e.src)!.push(e.dst);\n    preds.get(e.dst)!.push(e.src);\n  }\n  return { preds, succs };\n}\n\nexport function buildLayersFromRanks(\n  g: Graph,\n  order: NodeId[],\n  rankOf: Record<NodeId, number>,\n  opts?: { skipGroups?: boolean }\n): NodeId[][] {\n  let maxRank = 0;\n  for (const v of g.nodes) {\n    if (opts?.skipGroups && g.nodeById.get(v)?.isGroup) {\n      continue;\n    }\n    maxRank = Math.max(maxRank, rankOf[v] ?? 0);\n  }\n\n  const layers: NodeId[][] = Array.from({ length: maxRank + 1 }, () => []);\n  for (const v of order) {\n    if (opts?.skipGroups && g.nodeById.get(v)?.isGroup) {\n      continue;\n    }\n    layers[Math.max(0, rankOf[v] ?? 0)].push(v);\n  }\n  return layers;\n}\n\n// Detect acyclicity via DFS (white/gray/black sets)\nexport function isAcyclic(g: Graph): boolean {\n  const color: Record<NodeId, 0 | 1 | 2> = Object.create(null);\n  for (const v of g.nodes) {\n    color[v] = 0; // 0 white, 1 gray, 2 black\n  }\n\n  const adj = buildSuccessorMap(g);\n\n  const dfs = (u: NodeId): boolean => {\n    color[u] = 1; // gray\n    for (const v of adj.get(u) ?? []) {\n      if (color[v] === 0 && !dfs(v)) {\n        return false;\n      }\n      if (color[v] === 1) {\n        // back-edge\n        return false;\n      }\n    }\n    color[u] = 2; // black\n    return true;\n  };\n\n  for (const v of g.nodes) {\n    if (color[v] === 0 && !dfs(v)) {\n      return false;\n    }\n  }\n  return true;\n}\n\n// Topological sort (Kahn). Returns null if cycles exist.\nexport function topoSortIfAcyclic(g: Graph): NodeId[] | null {\n  const indeg = buildInDegreeMap(g);\n  const queue = sortedZeroInDegreeNodes(indeg);\n  const order: NodeId[] = [];\n  const adj = buildSortedSuccessorMap(g);\n\n  while (queue.length) {\n    const u = queue.shift()!;\n    order.push(u);\n    for (const v of adj.get(u) ?? []) {\n      indeg.set(v, (indeg.get(v) ?? 0) - 1);\n      if ((indeg.get(v) ?? 0) === 0) {\n        // insert keeping sorted order for determinism\n        let i = 0;\n        while (i < queue.length && queue[i] < v) {\n          i++;\n        }\n        queue.splice(i, 0, v);\n      }\n    }\n  }\n\n  return order.length === g.nodes.length ? order : null;\n}\n\n/**\n * Build an index map from node IDs to their positions in a layer.\n * This is used for efficient lookups during crossing minimization.\n */\nexport function buildLayerIndex(layer: NodeId[]): Map<NodeId, number> {\n  const m = new Map<NodeId, number>();\n  let index = 0;\n  for (const id of layer) {\n    m.set(id, index);\n    index++;\n  }\n  return m;\n}\n\nexport function countInversions(values: number[]): number {\n  const tmp = new Array<number>(values.length);\n  const count = (left: number, right: number): number => {\n    if (right - left <= 1) {\n      return 0;\n    }\n    const mid = (left + right) >> 1;\n    let inversions = count(left, mid) + count(mid, right);\n    let i = left;\n    let j = mid;\n    let k = left;\n    while (i < mid || j < right) {\n      if (j >= right || (i < mid && values[i] <= values[j])) {\n        tmp[k++] = values[i++];\n      } else {\n        tmp[k++] = values[j++];\n        inversions += mid - i;\n      }\n    }\n    for (let t = left; t < right; t++) {\n      values[t] = tmp[t];\n    }\n    return inversions;\n  };\n  return count(0, values.length);\n}\n", "import type { Graph, Edge, EdgeRef, NodeId } from './helpers.js';\nimport { normalizeGraph } from './phase0.helpers.js';\n// cspell:ignore Graphviz acyc Eades\n\nexport interface CycleRemovalResult {\n  acyclic: Graph;\n  reversed: Edge[]; // edges that were reversed (original orientation)\n}\n\n// Deterministic DFS-based cycle removal (similar to Graphviz dot back-edge marking)\nexport function removeCycles_DFS(g: Graph): CycleRemovalResult {\n  const gn = normalizeGraph(g);\n\n  // Build adjacency with deterministic order\n  const adj = new Map<NodeId, EdgeRef[]>();\n  for (const v of gn.nodes) {\n    adj.set(v, []);\n  }\n  for (const e of gn.edges) {\n    adj.get(e.src)!.push(e);\n  }\n  for (const arr of adj.values()) {\n    arr.sort((a, b) => (a.dst === b.dst ? a.id.localeCompare(b.id) : a.dst.localeCompare(b.dst)));\n  }\n\n  const color: Record<NodeId, 0 | 1 | 2> = Object.create(null);\n  for (const v of gn.nodes) {\n    color[v] = 0; // 0 white, 1 gray, 2 black\n  }\n\n  const reversed: EdgeRef[] = [];\n\n  const dfs = (u: NodeId) => {\n    color[u] = 1;\n    for (const e of adj.get(u) ?? []) {\n      const v = e.dst;\n      if (color[v] === 0) {\n        dfs(v);\n      } else if (color[v] === 1) {\n        // back-edge u->v; mark for reversal\n        reversed.push(e);\n      }\n    }\n    color[u] = 2;\n  };\n\n  // Visit in deterministic order\n  const nodesSorted = [...gn.nodes].sort((a, b) => a.localeCompare(b));\n  for (const v of nodesSorted) {\n    if (color[v] === 0) {\n      dfs(v);\n    }\n  }\n\n  // Build acyclic edge set by reversing all marked edges\n  const toReverse = new Set<string>(reversed.map((e) => `${e.id}:${e.src}->${e.dst}`));\n  const acycEdges: EdgeRef[] = gn.edges.map((e) =>\n    toReverse.has(`${e.id}:${e.src}->${e.dst}`)\n      ? { id: e.id, src: e.dst, dst: e.src, weight: e.weight, ref: e.ref }\n      : e\n  );\n\n  const acyclic: Graph = {\n    nodes: [...gn.nodes],\n    edges: acycEdges,\n    layout: gn.layout,\n    nodeById: new Map(gn.nodeById),\n  };\n  return { acyclic, reversed };\n}\n", "import type { Graph, NodeId } from './helpers.js';\n\n/**\n * Options controlling how layers are assigned in the Sugiyama pipeline.\n */\nexport interface LayeringOptions {\n  /** If true, a node with exactly one incoming edge inherits its predecessor's layer. */\n  compactSingleInput?: boolean;\n  /** If true, ignore edges from other lanes when calculating layer positions. */\n  ignoreCrossLaneEdges?: boolean;\n  /** If true, try to lift nodes to reduce crossings between layers. */\n  optimizeRanksByCrossings?: boolean;\n  /** Diagram direction, used by lane-aware rank heuristics with direction-specific failure modes. */\n  direction?: 'TB' | 'LR' | 'BT' | 'RL';\n}\n\n/**\n * Computes the \"top lane\" (outermost group container) for each node.\n *\n * Returns a map from node id -\\> lane id (top-level group) or null if the node\n * does not belong to any lane.\n */\nexport function buildTopLaneMap(g: Graph): Map<NodeId, string | null> {\n  const cache = new Map<NodeId, string | null>();\n\n  const resolve = (id: NodeId): string | null => {\n    if (cache.has(id)) {\n      return cache.get(id)!;\n    }\n    const node = g.nodeById.get(id) as any;\n    if (!node) {\n      cache.set(id, null);\n      return null;\n    }\n    const parentId = node.parentId as NodeId | undefined;\n    if (!parentId) {\n      cache.set(id, null);\n      return null;\n    }\n    const parentLane = resolve(parentId);\n    const lane = parentLane ?? parentId;\n    cache.set(id, lane);\n    return lane;\n  };\n\n  for (const id of g.nodes) {\n    resolve(id);\n  }\n  return cache;\n}\n\nexport function createTopLaneResolver(g: Graph): (id: NodeId) => string | null {\n  const topLaneMap = buildTopLaneMap(g);\n  return (id: NodeId): string | null => topLaneMap.get(id) ?? null;\n}\n\nexport function buildTopLaneOrder(g: Graph): string[] {\n  const lanes: string[] = [];\n  for (const node of g.layout.nodes ?? []) {\n    if (node.isGroup && !node.parentId) {\n      lanes.push(node.id);\n    }\n  }\n  return [...new Set(lanes)].reverse();\n}\n\nexport function resolveTopLaneOrder(g: Graph, preferredOrder?: string[]): string[] {\n  const sourceOrder = buildTopLaneOrder(g);\n  if (!preferredOrder || preferredOrder.length === 0) {\n    return sourceOrder;\n  }\n\n  const sourceLaneIds = new Set(sourceOrder);\n  const seen = new Set<string>();\n  const resolved: string[] = [];\n  for (const laneId of preferredOrder) {\n    if (!sourceLaneIds.has(laneId) || seen.has(laneId)) {\n      continue;\n    }\n    seen.add(laneId);\n    resolved.push(laneId);\n  }\n  for (const laneId of sourceOrder) {\n    if (seen.has(laneId)) {\n      continue;\n    }\n    resolved.push(laneId);\n  }\n  return resolved;\n}\n", "/**\n * Configuration constants for the Swimlanes layout algorithm.\n * Centralizes all magic numbers and default values for maintainability.\n */\n\n/**\n * Edge routing and spacing constants\n */\nexport const EDGE_ROUTING = {\n  /** Spacing between parallel edges in the same corridor (px) */\n  EDGE_GAP: 12,\n\n  /** Horizontal offset from lane boundary to corridor center (px) */\n  LANE_MARGIN: 20,\n} as const;\n\n/**\n * Numerical precision constants\n */\nexport const PRECISION = {\n  /** Epsilon for floating-point comparisons */\n  EPSILON: 1e-6,\n} as const;\n\n/**\n * Layer assignment constants\n */\nexport const LAYERING = {\n  /** Default number of iterations for gravity-based layering */\n  GRAVITY_ITERATIONS: 8,\n\n  /** Maximum number of passes for crossing-based rank optimization */\n  MAX_CROSSING_OPTIM