 upperIdx = indexOf.get(src);\n    const lowerIdx = indexOf.get(dst);\n    if (upperIdx == null || lowerIdx == null) {\n      continue;\n    }\n    const lca = lcaIndex(upperIdx, lowerIdx);\n    if (lca === -1) {\n      continue;\n    }\n    const bucket = ownCounts[lca];\n    for (let layer = ru; layer < rv; layer++) {\n      bucket.set(layer, (bucket.get(layer) ?? 0) + 1);\n    }\n  }\n\n  const crossCounts = new Map<NodeId, Map<NodeId, number>>();\n\n  const mergeInto = (target: Map<number, number>, source: Map<number, number>) => {\n    if (source.size === 0) {\n      return;\n    }\n    for (const [layer, value] of source) {\n      target.set(layer, (target.get(layer) ?? 0) + value);\n    }\n  };\n\n  const visited = new Set<NodeId>();\n  const dfs = (node: NodeId): Map<number, number> => {\n    const idx = indexOf.get(node);\n    visited.add(node);\n    const base = idx == null ? undefined : ownCounts[idx];\n    const accumulator = base ? new Map<number, number>(base) : new Map<number, number>();\n    const childList = tree.children.get(node) ?? [];\n    for (const child of childList) {\n      const childMap = dfs(child);\n      const parentLayer = rankOf[node];\n      if (parentLayer != null) {\n        let map = crossCounts.get(node);\n        if (!map) {\n          map = new Map<NodeId, number>();\n          crossCounts.set(node, map);\n        }\n        let value = childMap.get(parentLayer) ?? 0;\n        const childLayer = rankOf[child];\n        if (childLayer != null && childLayer > parentLayer) {\n          value += 1;\n        }\n        map.set(child, value);\n      }\n      mergeInto(accumulator, childMap);\n    }\n    return accumulator;\n  };\n\n  for (const root of tree.roots) {\n    if (!visited.has(root)) {\n      dfs(root);\n    }\n  }\n  for (const node of nodes) {\n    if (!visited.has(node)) {\n      dfs(node);\n    }\n  }\n\n  return crossCounts;\n}\n", "import type { NodeId } from './helpers.js';\n\n// cspell:ignore multitree\n/**\n * Utilities shared by the multitree-based layer ordering logic.\n */\nexport function annotateMinimumLayers(\n  nodes: NodeId[],\n  children: Map<NodeId, NodeId[]>,\n  rankOf: Record<NodeId, number>\n): Map<NodeId, number> {\n  const minLayer = new Map<NodeId, number>();\n\n  const annotate = (node: NodeId) => {\n    let minL = rankOf[node] ?? 0;\n    const childList = [...(children.get(node) ?? [])];\n    childList.sort(compareByRankThenId(rankOf));\n    for (const child of childList) {\n      annotate(child);\n      const childMin = minLayer.get(child);\n      if (childMin != null) {\n        minL = Math.min(minL, childMin);\n      }\n    }\n    minLayer.set(node, minL);\n  };\n\n  for (const node of nodes) {\n    annotate(node);\n  }\n\n  return minLayer;\n}\n\nexport function compareByRankThenId(rankOf: Record<NodeId, number>) {\n  return (a: NodeId, b: NodeId) => {\n    const ra = rankOf[a] ?? 0;\n    const rb = rankOf[b] ?? 0;\n    return ra === rb ? a.localeCompare(b) : ra - rb;\n  };\n}\n\n/**\n * Emits nodes into layers in tree traversal order, using the provided\n * orderChildren function to determine the order of children.\n */\nexport function emitNodesInTreeOrder(\n  roots: NodeId[],\n  allNodes: NodeId[],\n  rankOf: Record<NodeId, number>,\n  orderChildren: (node: NodeId) => NodeId[]\n): NodeId[][] {\n  let maxRank = 0;\n  for (const node of allNodes) {\n    const r = rankOf[node] ?? 0;\n    if (r > maxRank) {\n      maxRank = r;\n    }\n  }\n\n  const layers: NodeId[][] = Array.from({ length: maxRank + 1 }, () => []);\n  const emitted = new Set<NodeId>();\n\n  const emit = (node: NodeId) => {\n    if (emitted.has(node)) {\n      return;\n    }\n    emitted.add(node);\n    const layer = rankOf[node] ?? 0;\n    if (!layers[layer]) {\n      layers[layer] = [];\n    }\n    layers[layer].push(node);\n    for (const child of orderChildren(node)) {\n      emit(child);\n    }\n  };\n\n  for (const root of roots) {\n    emit(root);\n  }\n\n  // Fallback for isolat